mapper.select:
select path from sys_upload_file_info a where exists (
select 1 from CHB_PRD_DECLARE_INFO b where
a.seq_no = b.file_no

    and b.PROD_INS_ID = #{prodInsId}

)  limit 1

mapper.update:
update CHB_PRD_DECLARE_INFO
set FILE_NO=#{fileNo},
FILE_NUM=#{fileNum},
TEN_FILE = #{tenFile}


        DECLARE_UUID = #{declareUuid}


        PROD_INS_ID = #{prodInsId}
